// v3 frame animation: sprite-atlas loading (lazy, per hero / per zone) + animation state machine for heroes, monsters and bosses.
// Atlases are generated by tools/process_anim.py (cells aligned on the feet, one common scale per sheet) -> see atlasmeta.js.
(function () {
  const PW = window.PW, G = PW.G, U = PW.U;
  const AT = (G.atl = {}), req = {}, retry = {}; // loaded atlases {img, white, meta}, requested keys
  // hero frames: 0-3 walk, 4-6 attack, 7 hurt, 8-10 cast, 11 idle alt.   monster frames: 0-3 walk, 4-6 attack, 7 hurt
  const WALK = [0, 1, 2, 3], IDLE_H = [11, 11, 0, 11], IDLE_M = [0, 1, 2, 1];
  PW.ANIM = { WALK, HURT: 7, ATTACK: [4, 5, 6], CAST: [8, 9, 10] };

  PW.loadAtlas = (key) => {
    if (AT[key] || req[key] || !PW.ATLAS || !PW.ATLAS[key]) return req[key];
    const meta = PW.ATLAS[key];
    return (req[key] = new Promise((res) => {
      const im = new Image(); im.decoding = "async";
      im.onload = () => {
        const a = { img: im, meta, white: null };
        // hit-flash silhouette (skipped on low graphics to save memory)
        a.mkWhite = () => { if (a.white) return a.white; const c = document.createElement("canvas"); c.width = im.width; c.height = im.height; const g = c.getContext("2d"); g.drawImage(im, 0, 0); g.globalCompositeOperation = "source-in"; g.fillStyle = "#fff"; g.fillRect(0, 0, c.width, c.height); return (a.white = c); };
        AT[key] = a; res(a);
      };
      im.onerror = () => { res(null); const n = (retry[key] = (retry[key] || 0) + 1); if (n <= 3) setTimeout(() => { delete req[key]; }, 1500 * n); }; // transient network error: allow a later retry (static sprite is the fallback meanwhile)
      im.src = PW.sprUrl("atlas_" + key);
    }));
  };
  // heroes that are on the field, and monsters of the zones near the player, are loaded on demand
  PW.ensureAtlases = () => {
    if (!G.hero) return; PW.loadAtlas("hero_" + G.hero.id); for (const a of G.allies) PW.loadAtlas("hero_" + a.id);
    const z = PW.zoneAt(G.hero.x, G.hero.y).id; PW.zoneAtlases(z);
  };
  const ORDER = ["meadow", "forest", "desert", "ice"];
  PW.zoneAtlases = (zid) => {
    const zi = ORDER.indexOf(zid); const ids = zi < 0 ? ["meadow"] : [ORDER[zi]];
    for (const m of Object.keys(PW.MONSTERS)) if (ids.includes(PW.MONSTERS[m].zone)) PW.loadAtlas("mon_" + m);
  };
  PW.prefetchNextZone = (zid) => { const zi = ORDER.indexOf(zid); const n = ORDER[zi + 1]; if (n) PW.zoneAtlases(n); };

  // trigger a timed animation state on a hero/monster: kind = attack | cast
  PW.setAnim = (e, kind, dur) => { e.an = { k: kind, t0: G.t, dur: dur || 0.35 }; };
  const prog = (e) => { const a = e.an; if (!a) return -1; const p = (G.t - a.t0) / a.dur; if (p >= 1) { e.an = null; return -1; } return Math.max(0, p); };

  // returns {frame, state, p} for a hero
  PW.heroFrame = (h, t) => {
    if (h.dead) return { f: 7, s: "dead", p: Math.min(1, (t - (h.deadAt || t)) / 0.5) };
    const p = prog(h);
    if (p >= 0) { const arr = h.an.k === "cast" ? PW.ANIM.CAST : PW.ANIM.ATTACK; return { f: arr[Math.min(2, Math.floor(p * 3))], s: h.an.k, p }; }
    if (h.hurt > 0 && h.hurt > 0.06) return { f: 7, s: "hurt", p: 0 };
    if (h.moving) return { f: WALK[Math.floor(t * 11 + (h.idx || 0) * 1.3) & 3], s: "walk", p: 0 };
    return { f: IDLE_H[Math.floor(t * 2.4 + (h.idx || 0)) & 3], s: "idle", p: 0 };
  };
  PW.monFrame = (m, t, mv) => {
    const p = prog(m);
    if (p >= 0) return { f: PW.ANIM.ATTACK[Math.min(2, Math.floor(p * 3))], s: "attack", p };
    if (m.hurt > 0) return { f: 7, s: "hurt", p: 0 };
    if (mv) return { f: WALK[Math.floor(t * (m.type === "slime" ? 6 : 9) + m.seed * 3) & 3], s: "walk", p: 0 };
    return { f: IDLE_M[Math.floor(t * 2.2 + m.seed * 5) & 3], s: "idle", p: 0 };
  };

  // draw atlas frame: H = world height of the character body (bodyH in sheet px), anchored at feet (bottom-centre)
  PW.drawFrame = (c, key, f, x, y, H, flip, sx, sy, hurt, alpha, rot) => {
    const a = AT[key]; if (!a) return false; const m = a.meta, k = H / m.bodyH, cs = m.cell * k, col = f % m.cols, row = (f / m.cols) | 0;
    c.save(); c.translate(x, y); if (rot) c.rotate(rot); c.scale((flip ? -1 : 1) * (sx || 1), sy || 1); if (alpha != null) c.globalAlpha = alpha;
    const dx = -cs / 2, dy = -cs + 4 * k;
    c.drawImage(a.img, col * m.cell, row * m.cell, m.cell, m.cell, dx, dy, cs, cs);
    if (hurt > 0) { const w = a.mkWhite(); c.globalAlpha = Math.min(1, hurt) * (alpha != null ? alpha : 1); c.drawImage(w, col * m.cell, row * m.cell, m.cell, m.cell, dx, dy, cs, cs); }
    c.restore(); return true;
  };
  PW.hasAtlas = (key) => !!AT[key];
})();
